  const baseHalfWidth = classTag === 'A'
    ? 980
    : classTag === 'B'
      ? 760
      : classTag === 'C'
        ? 520
        : 260;
  const widening = normalAirport ? beyond * 0.06 : beyond * 0.03;
  const halfWidth = Math.max(runwayWidth * 3.6, baseHalfWidth + widening);
  const corridor = 1 - smoothstep(halfWidth, halfWidth + (normalAirport ? 520 : 240), Math.abs(local.x));
  if (corridor <= 0) return height;

  const fade = 1 - smoothstep(extension * 0.72, extension, beyond);
  const elevation = airport.elevation || 0;
  const slope = normalAirport ? 0.047 : 0.054;
