  const size = Math.sqrt(island.rx * island.rz);
  const lowlandRise = Math.max(0, 1 - n / 1.06) * (8 + Math.min(18, size * 0.006));
  const shoulder = Math.pow(Math.max(0, 1 - n / 0.88), 1.55) * (size > 1100 ? 20 : size > 780 ? 12 : 6);
